head.b:skin:
/* ================================================================
   PlusWall 1.0.3 — Blogger theme
   Theme styles, layout, and widgets for the PlusWall interface.
   ================================================================ */
/*! normalize.css v3.0.1 | MIT License | git.io/normalize */html{font-family:sans-serif;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%}body{margin:0}article,aside,details,figcaption,figure,footer,header,hgroup,main,nav,section,summary{display:block}audio,canvas,progress,video{display:inline-block;vertical-align:baseline}audio:not([controls]){display:none;height:0}[hidden],template{display:none}a{background:transparent}a:active,a:hover{outline:0}abbr[title]{border-bottom:1px dotted}b,strong{font-weight:bold}dfn{font-style:italic}h1{font-size:2em;margin:.67em 0}mark{background:#ff0;color:#000}small{font-size:80%}sub,sup{font-size:75%;line-height:0;position:relative;vertical-align:baseline}sup{top:-0.5em}sub{bottom:-0.25em}img{border:0}svg:not(:root){overflow:hidden}figure{margin:1em 40px}hr{-moz-box-sizing:content-box;box-sizing:content-box;height:0}pre{overflow:auto}code,kbd,pre,samp{font-family:monospace,monospace;font-size:1em}button,input,optgroup,select,textarea{color:inherit;font:inherit;margin:0}button{overflow:visible}button,select{text-transform:none}button,html input[type="button"],input[type="reset"],input[type="submit"]{-webkit-appearance:button;cursor:pointer}button[disabled],html input[disabled]{cursor:default}button::-moz-focus-inner,input::-moz-focus-inner{border:0;padding:0}input{line-height:normal}input[type="checkbox"],input[type="radio"]{box-sizing:border-box;padding:0}input[type="number"]::-webkit-inner-spin-button,input[type="number"]::-webkit-outer-spin-button{height:auto}input[type="search"]{-webkit-appearance:textfield;-moz-box-sizing:content-box;-webkit-box-sizing:content-box;box-sizing:content-box}input[type="search"]::-webkit-search-cancel-button,input[type="search"]::-webkit-search-decoration{-webkit-appearance:none}fieldset{border:1px solid #c0c0c0;margin:0 2px;padding:.35em .625em .75em}legend{border:0;padding:0}textarea{overflow:auto}optgroup{font-weight:bold}table{border-collapse:collapse;border-spacing:0}td,th{padding:0}

/* Independent Pluswall baseline rules replacing two inherited browser defaults. */
a { text-decoration: none; }
.skip-navigation { position: absolute; left: 0; top: -100px; width: 1px; height: 1px; overflow: hidden; }
.skip-navigation:focus { position: fixed; top: 0; left: 0; width: auto; height: auto; padding: 12px; background: white; z-index: 9999; }

/* ====================================================================
   PLUSWALL PRESENTATION
   Blogger renders post bodies and jump breaks on the server.
   PlusWall positions existing post cards without modifying their content.
   Blogger handles post bodies, comments, and native jump breaks.
   ==================================================================== */

:root{
--pluswall-page-background:#e5e5e5;
--pluswall-card-background:#ffffff;
--pluswall-border-color:#d9d9d9;
--pluswall-text-color:#333333;
--pluswall-secondary-text-color:#8a8a8a;
--pluswall-link-color:#427fed;
--pluswall-accent-color:#dd4b39;
--pluswall-layout-gap:14px
}
html,body{
background:var(--pluswall-page-background)!important
}
body{
color:var(--pluswall-text-color)!important;
font-family:Arial,Helvetica,sans-serif!important;
font-size:13px!important;
line-height:1.5!important;
margin:0!important
}
a{
color:var(--pluswall-link-color)
}
.pluswall-site-header{
background:#ffffff;
border-bottom:1px solid #ececec;
height:49px
}
.pluswall-site-header-content{
align-items:center;
display:flex;
gap:24px;
height:49px;
margin:0 auto;
max-width:1240px;
padding:0 18px
}
.pluswall-site-title{
color:#777777!important;
font-family:Georgia,"Times New Roman",serif;
font-size:23px;
font-weight:700;
letter-spacing:-1px;
line-height:1;
white-space:nowrap
}
.pluswall-site-title:hover{
text-decoration:none
}
.pluswall-site-title-mark{
color:var(--pluswall-accent-color);
font-family:Arial,Helvetica,sans-serif;
font-size:18px;
font-weight:400;
letter-spacing:0;
position:relative;
top:-2px
}
.pluswall-search-form{
display:flex;
height:28px;
max-width:426px;
width:44vw
}
.pluswall-search-input{
background:#ffffff;
border:1px solid #d4d4d4;
flex:1;
min-width:0;
outline:0;
padding:4px 9px
}
.pluswall-search-input:focus{
border-color:#8cafea;
box-shadow:inset 0 0 1px #9fc2fd
}
.pluswall-search-button{
background:var(--pluswall-link-color);
border:0;
color:#ffffff;
min-width:46px;
padding:0 12px
}
.pluswall-subscription-link{
font-size:12px;
font-weight:700;
margin-left:auto
}
.pluswall-collection-navigation{
background:#f5f5f5;
border-bottom:1px solid #d6d6d6;
min-height:42px
}
.pluswall-collection-list{
align-items:center;
display:flex;
gap:29px;
margin:0 auto;
max-width:1240px;
min-height:42px;
overflow-x:auto;
padding:0 18px
}
.pluswall-collection-link{
align-items:center;
border-bottom:2px solid transparent;
color:#777777!important;
display:flex;
font-size:12px;
height:42px;
padding:0 2px;
white-space:nowrap
}
.pluswall-collection-link:hover,
.pluswall-collection-link.pluswall-current-collection{
border-bottom-color:var(--pluswall-link-color);
color:#333333!important;
text-decoration:none
}
body:not(#layout) .centered-top-container,
body:not(#layout) .centered-top-placeholder,
body:not(#layout) .bg-photo-container,
body:not(#layout) .featured-post,
body:not(#layout) .vertical-ad-container,
body:not(#layout) .sidebar-container,
body:not(#layout) .main-heading,
body:not(#layout) .page>.footer{
display:none!important
}
body:not(#layout) .page,
body:not(#layout) .page_body,
body:not(#layout) .centered,
body:not(#layout) .centered-bottom{
background:var(--pluswall-page-background)!important;
margin:0!important;
max-width:none!important;
min-width:0!important;
padding:0!important;
width:100%!important
}
body:not(#layout) .main-container{
display:block!important;
float:none!important;
margin:20px auto 65px!important;
max-width:1170px!important;
padding:0 14px!important;
width:auto!important
}
body:not(#layout) #page_body,
body:not(#layout) #page_body>.widget.Blog{
float:none!important;
margin:0!important;
max-width:none!important;
padding:0!important;
position:static!important;
top:auto!important;
z-index:auto!important;
width:100%!important
}
.post-filter-message{
background:#ffffff!important;
border:1px solid var(--pluswall-border-color)!important;
box-sizing:border-box;
font-size:13px!important;
margin:0 auto 14px!important;
max-width:1142px!important;
padding:11px 15px!important
}
.Blog .blog-posts,
.Blog .post-outer,
.Blog .post-outer-container{
margin:0!important;
padding:0!important
}
.Blog .blog-posts{
width:100%!important
}
.feed-view .Blog .blog-posts{
column-count:3;
column-gap:var(--pluswall-layout-gap)
}
.feed-view .Blog .blog-posts>*{
break-inside:avoid;
display:inline-block;
margin:0 0 var(--pluswall-layout-gap)!important;
page-break-inside:avoid;
vertical-align:top;
width:100%
}
.feed-view .Blog .blog-posts.pluswall-layout-ready{
column-count:auto;
display:block;
position:relative
}
.feed-view .Blog .blog-posts.pluswall-layout-ready>.pluswall-post-container{
display:block;
margin:0!important;
position:absolute
}
.pluswall-post-card{
background:var(--pluswall-card-background);
border:1px solid var(--pluswall-border-color);
box-shadow:0 1px 1px rgba(0,0,0,.04);
box-sizing:border-box;
overflow:hidden;
width:100%
}
.pluswall-post-header{
align-items:center;
display:flex;
gap:10px;
padding:13px 13px 8px
}
.pluswall-author-image,
.pluswall-author-image-fallback{
border:1px solid #cbdbea;
border-radius:50%;
box-sizing:border-box;
flex:0 0 36px;
height:36px;
object-fit:cover;
width:36px
}
.pluswall-author-image-fallback{
align-items:center;
background:#d8e7f8;
color:#587eaf;
display:flex;
font-size:16px;
font-weight:700;
justify-content:center
}
.pluswall-post-identification{
flex:1;
line-height:1.3;
min-width:0
}
.pluswall-author-name{
color:#484848;
display:block;
font-size:13px;
font-weight:700
}
.pluswall-post-date{
color:var(--pluswall-secondary-text-color);
font-size:11px;
margin-top:3px
}
.pluswall-post-date a{
color:inherit
}
.pluswall-permalink-mark{
align-self:flex-start;
color:#aaaaaa;
font-size:17px;
line-height:1;
padding:0 1px 3px 6px
}
.pluswall-permalink-mark:hover{
color:var(--pluswall-link-color);
text-decoration:none
}
.pluswall-post-title{
color:#444444;
font-size:15px;
font-weight:600;
line-height:1.35;
margin:4px 13px 9px;
overflow-wrap:anywhere
}
.pluswall-post-title a{
color:inherit
}
.pluswall-post-content{
overflow-wrap:anywhere;
padding:2px 13px 8px
}
.pluswall-post-body{
color:var(--pluswall-text-color)!important;
float:none!important;
font-family:Arial,Helvetica,sans-serif!important;
font-size:13px!important;
line-height:1.57!important;
margin:0!important;
min-width:0;
overflow-wrap:anywhere;
width:auto!important
}
.pluswall-post-body>:first-child{
margin-top:0!important
}
.pluswall-post-body p{
margin:0 0 11px
}
.pluswall-post-body blockquote{
border-left:3px solid #dddddd;
color:#666666;
margin:12px 0;
padding:5px 12px
}
.pluswall-post-body h1,
.pluswall-post-body h2,
.pluswall-post-body h3{
font-size:15px;
line-height:1.4;
margin:16px 0 8px
}
.pluswall-post-body ul,
.pluswall-post-body ol{
margin:10px 0;
padding-left:22px
}
.pluswall-post-body pre{
background:#f7f7f7;
border:1px solid #ececec;
overflow-x:auto;
padding:10px;
white-space:pre-wrap
}
.pluswall-post-body img{
display:block!important;
float:none!important;
height:auto!important;
margin:4px auto!important;
max-width:100%!important;
object-fit:contain!important;
width:auto!important
}
.pluswall-post-body .separator,
.pluswall-post-body .tr-caption-container{
clear:both!important;
float:none!important;
margin:9px auto!important;
max-width:100%!important;
text-align:center!important;
width:100%!important
}
.pluswall-post-body .separator a{
display:inline-block;
max-width:100%
}
.feed-view .pluswall-post-body .separator,
.feed-view .pluswall-post-body .tr-caption-container{
margin:4px -13px!important;
max-width:calc(100% + 26px)!important;
width:calc(100% + 26px)!important
}
.feed-view .pluswall-post-body .separator a{
display:block!important;
margin-left:0!important;
margin-right:0!important;
max-width:none!important;
width:100%!important
}
.feed-view .pluswall-post-body .separator img,
.feed-view .pluswall-post-body .tr-caption-container img{
margin:0!important;
max-width:none!important;
width:100%!important
}
.feed-view .pluswall-post-body>a[imageanchor]{
display:block!important;
margin:4px -13px!important;
max-width:calc(100% + 26px)!important;
width:calc(100% + 26px)!important
}
.feed-view .pluswall-post-body>a[imageanchor]>img{
margin:0!important;
max-width:none!important;
width:100%!important
}
.feed-view .pluswall-post-body>img{
margin:4px -13px!important;
max-width:calc(100% + 26px)!important;
width:calc(100% + 26px)!important
}
.pluswall-post-body iframe,
.pluswall-post-body video{
height:auto;
max-width:100%!important
}
.pluswall-post-body table{
max-width:100%!important
}
.pluswall-post-body a{
overflow-wrap:anywhere
}
.pluswall-jump-link{
font-size:12px;
font-weight:700;
margin:6px 0 2px
}
.pluswall-label-list{
display:flex;
flex-wrap:wrap;
gap:5px;
padding:1px 13px 10px
}
.pluswall-label-link{
background:#f3f3f3;
color:#888888!important;
font-size:10px;
padding:2px 6px
}
.pluswall-label-link:hover{
background:#e8eef9;
color:#376abb!important;
text-decoration:none
}
.pluswall-post-actions{
align-items:center;
border-top:1px solid #eeeeee;
color:#999999;
display:flex;
font-size:11px;
gap:8px;
padding:9px 12px 10px
}
.pluswall-action-link{
background:#ffffff;
border:1px solid #e5e5e5;
color:#777777!important;
line-height:22px;
min-height:24px;
padding:0 8px
}
.pluswall-action-link:hover{
background:#f9f9f9;
color:#444444!important;
text-decoration:none
}
.pluswall-permanent-link{
color:#aaaaaa!important;
margin-left:auto;
white-space:nowrap
}
.item-view .main-container{
font-size:15px!important;
max-width:calc(65ch + 40px)!important
}
.item-view .pluswall-post-header{
padding:18px 20px 9px
}
.item-view .pluswall-post-title{
font-size:23px;
font-weight:500;
margin:6px 20px 14px
}
.item-view .pluswall-post-content{
padding:9px 20px 18px
}
.item-view .pluswall-post-body{
font-size:15px!important;
line-height:1.7!important
}
.item-view .pluswall-label-list,
.item-view .pluswall-post-actions{
padding-left:20px;
padding-right:20px
}
.item-view #comments{
background:#ffffff!important;
border:1px solid var(--pluswall-border-color)!important;
box-sizing:border-box;
margin:14px 0 0!important;
max-width:none!important;
padding:20px!important
}
.item-view #comments .comment-form,
.item-view #comments .comments-content{
max-width:none!important
}
.blog-pager{
clear:both;
display:flex!important;
gap:14px;
justify-content:space-between;
margin:22px 0!important;
padding:0 3px!important
}
.blog-pager a{
background:#ffffff;
border:1px solid var(--pluswall-border-color);
color:#666666!important;
padding:8px 14px
}
@media(max-width:1040px){
.feed-view .Blog .blog-posts{
column-count:2
}
body:not(#layout) .main-container{
max-width:820px!important
}
}
@media(max-width:680px){
.pluswall-site-header-content{
gap:10px;
padding:0 11px
}
.pluswall-site-title{
font-size:19px
}
.pluswall-search-form{
flex:1;
width:auto
}
.pluswall-subscription-link{
display:none
}
.pluswall-collection-list{
gap:20px;
padding:0 12px
}
body:not(#layout) .main-container{
margin-top:12px!important;
max-width:510px!important;
padding:0 11px!important
}
.feed-view .Blog .blog-posts{
column-count:1
}
.item-view .pluswall-post-header{
padding:13px 13px 8px
}
.item-view .pluswall-post-title{
font-size:20px;
margin:5px 13px 12px
}
.item-view .pluswall-post-content{
padding:7px 13px 12px
}
.item-view .pluswall-label-list,
.item-view .pluswall-post-actions{
padding-left:13px;
padding-right:13px
}
.item-view #comments{
padding:12px!important
}
}

/* ====================================================================
   PLUSWALL 4.9: BLOGGER HEADER1 COVER
   The existing Header gadget manages the cover art and description.
   Upload/change the art under Blogger > Layout > Header > Edit;
   choose "Behind title and description" and disable "Shrink to fit".
   This is presentation-only; all existing Blog1 rendering is retained.
   ==================================================================== */
body:not(#layout) .pluswall-cover-banner {
  box-sizing: border-box;
  margin: 0 auto;
  max-width: 1170px;
  padding: 0 14px;
  width: 100%;
}
body:not(#layout) .pluswall-cover-banner #header,
body:not(#layout) .pluswall-cover-banner #Header1 {
  box-sizing: border-box;
  display: block;
  float: none !important;
  margin: 0 !important;
  max-width: none !important;
  padding: 0 !important;
  width: 100% !important;
}
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget {
  align-items: flex-start;
  background-color: #263946;
  background-position: 50% 40% !important;
  background-repeat: no-repeat !important;
  background-size: cover !important;
  box-shadow: 0 1px 3px rgba(0,0,0,.16);
  box-sizing: border-box;
  color: #fff !important;
  display: flex;
  flex-direction: column;
  height: clamp(280px, 33vw, 405px);
  justify-content: flex-end;
  overflow: hidden;
  padding: 30px;
  position: relative;
  width: 100%;
}
/* Frosted panel occupying the left third; the cover art stays full-width. */
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget::before {
  background: rgba(9, 19, 30, .58);
  bottom: 0;
  content: '';
  left: 0;
  min-width: 290px;
  position: absolute;
  top: 0;
  width: 34%;
  -webkit-backdrop-filter: blur(7px);
  backdrop-filter: blur(7px);
}
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget > * {
  box-sizing: border-box;
  max-width: calc(34% - 12px);
  position: relative;
  z-index: 1;
}
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 {
  color: #fff !important;
  font: 700 28px/1.2 Arial, Helvetica, sans-serif !important;
  letter-spacing: 0;
  margin: 0 0 7px !important;
  text-shadow: 0 1px 2px rgba(0,0,0,.3);
}
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget p {
  color: rgba(255,255,255,.9) !important;
  font: 13px/1.45 Arial, Helvetica, sans-serif !important;
  margin: 0 !important;
}
@media (max-width: 680px) {
  body:not(#layout) .pluswall-cover-banner { padding: 0 11px; }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget {
    background-position: 100% 42% !important;
    height: 310px;
    padding: 22px;
  }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget::before {
    background: linear-gradient(to top, rgba(9,19,30,.85), rgba(9,19,30,.2));
    height: 55%;
    min-width: 0;
    top: auto;
    width: 100%;
  }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget > * {
    max-width: 100%;
  }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 {
    font-size: 23px !important;
  }
}


/* ====================================================================
   PLUSWALL 4.10: CHROME WIDTH ALIGNMENT
   Header, cover and collection navigation: 1240px maximum.
   The three-column post wall remains unchanged at 1170px.
   CSS-only revision; Blogger widgets and their rendering are untouched.
   ==================================================================== */
.pluswall-site-header-content,
.pluswall-collection-list {
  box-sizing: border-box;
  max-width: 1240px;
  width: 100%;
}
body:not(#layout) .pluswall-cover-banner {
  box-sizing: border-box;
  max-width: 1240px;
  padding-left: 0;
  padding-right: 0;
  width: 100%;
}
@media (max-width: 680px) {
  body:not(#layout) .pluswall-cover-banner {
    padding-left: 11px;
    padding-right: 11px;
  }
}


/* PLUSWALL 4.11: roughly 65 characters per line on individual posts.
   This must outrank body:not(#layout) .main-container above. */
body.item-view:not(#layout) .main-container {
  max-width: calc(65ch + 40px) !important;
}


/* ====================================================================
   PLUSWALL 1.0.3: COVER IDENTITY AND QUIETER POST WALL
   The banner avatar is rendered by the native Profile1 gadget.
   The Follow button opens Blogger's native follow interface; a live count
   is deliberately omitted because Blogger does not expose it to the theme.
   ==================================================================== */
body:not(#layout) .pluswall-cover-banner {
  position: relative;
}
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget {
  padding-left: 148px;
}
body:not(#layout) .pluswall-banner-avatar {
  align-items: center;
  background: rgba(220,232,242,.35);
  border: 3px solid rgba(255,255,255,.92);
  border-radius: 50%;
  bottom: 30px;
  box-shadow: 0 1px 6px rgba(0,0,0,.35);
  box-sizing: border-box;
  display: flex;
  height: 102px;
  justify-content: center;
  left: 30px;
  overflow: hidden;
  position: absolute;
  width: 102px;
  z-index: 3;
}
body:not(#layout) .pluswall-banner-avatar-image {
  display: none;
  height: 100%;
  object-fit: cover;
  width: 100%;
}
body:not(#layout) .pluswall-banner-avatar .pluswall-banner-avatar-image {
  display: block;
}
body:not(#layout) .pluswall-banner-actions {
  align-items: center;
  bottom: 27px;
  display: flex;
  gap: 8px;
  position: absolute;
  right: 30px;
  z-index: 3;
}
body:not(#layout) .pluswall-banner-actions a {
  background: rgba(9,19,30,.48);
  border-radius: 2px;
  color: #fff !important;
  font: 700 12px/1.4 Arial,Helvetica,sans-serif;
  padding: 7px 10px;
  text-decoration: none;
  text-shadow: 0 1px 1px rgba(0,0,0,.35);
}
body:not(#layout) .pluswall-banner-actions a:hover,
body:not(#layout) .pluswall-banner-actions a:focus {
  background: rgba(9,19,30,.75);
  text-decoration: underline;
}
/* On the wall only. Full posts retain their labels and native metadata. */
.feed-view .pluswall-permalink-mark,
.feed-view .pluswall-label-list {
  display: none !important;
}
@media (max-width: 680px) {
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget {
    padding-left: 108px;
  }
  body:not(#layout) .pluswall-banner-avatar {
    bottom: 22px;
    height: 70px;
    left: 33px;
    width: 70px;
  }
  body:not(#layout) .pluswall-banner-actions {
    bottom: auto;
    right: 24px;
    top: 16px;
  }
  body:not(#layout) .pluswall-banner-actions a {
    font-size: 11px;
  }
}



/* ====================================================================
   PLUSWALL 4.17: DESKTOP CHROME INSETS AND CENTERED POST WALL
   Header, navigation, and cover share a centered 1240px outer width.
   Header/nav text gains an 18px interior inset. The 1220px post wall is
   centered 10px in from both cover edges instead of flush at left.
   The mobile layout (680px or narrower) remains unchanged.
   ==================================================================== */
@media (min-width: 681px) {
  .pluswall-site-header-content,
  .pluswall-collection-list,
  body:not(#layout) .pluswall-cover-banner {
    box-sizing: border-box;
    margin-left: auto;
    margin-right: auto;
    max-width: 1240px;
    padding-left: 0;
    padding-right: 0;
    width: calc(100% - 36px);
  }

  .pluswall-site-header-content,
  .pluswall-collection-list {
    padding-left: 18px;
    padding-right: 18px;
  }

  body:not(#layout) .main-container {
    box-sizing: border-box;
    margin: 20px auto 65px !important;
    max-width: 1220px !important;
    padding: 0 !important;
    width: calc(100% - 56px) !important;
  }
}

/* Mobile only: end the tinted band roughly 30px above the avatar. */
@media (max-width: 680px) {
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget::before {
    height: 40%;
  }
}



/* ====================================================================
   PLUSWALL 4.15: PAGE-SPECIFIC PRESENTATION CORRECTIONS
   No Blogger widget or default-markup definitions changed.
   ==================================================================== */

/* Search stays at the right end of the header, beside RSS. */
.pluswall-search-form {
  margin-left: auto;
}
.pluswall-subscription-link {
  margin-left: 0;
}

/* The header title is a link on some Blogger views; keep it white. */
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 a,
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 a:link,
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 a:visited,
body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 a:hover {
  color: #fff !important;
}

/* Banner avatar: 2px white outline. */
body:not(#layout) .pluswall-banner-avatar {
  border-width: 2px;
}

/* Hide Blogger's search-result status box only on label/category pages. */
body.label-view:not(#layout) .post-filter-message {
  display: none !important;
}

/* Single post: it is already open, so suppress redundant links. */
body.item-view:not(#layout) .pluswall-permalink-mark,
body.item-view:not(#layout) .pluswall-permanent-link {
  display: none !important;
}


/* ====================================================================
   PLUSWALL 4.16: CONTAIN DESKTOP HEADER AND NAVIGATION BACKGROUNDS
   Keep the title/search and collection navigation aligned to the same
   1240px desktop grid as the cover banner, instead of full-width bands.
   Mobile retains its existing edge-to-edge treatment.
   ==================================================================== */
@media (min-width: 681px) {
  body:not(#layout) .pluswall-site-header,
  body:not(#layout) .pluswall-collection-navigation {
    background: transparent;
    border-bottom: 0;
  }
  body:not(#layout) .pluswall-site-header-content {
    background: #ffffff;
    border-bottom: 1px solid #ececec;
  }
  body:not(#layout) .pluswall-collection-list {
    background: #f5f5f5;
    border-bottom: 1px solid #d6d6d6;
  }
}


/* ====================================================================
   PLUSWALL 4.18: TABLET BANNER IDENTITY
   At 681–1100px, scale the profile text and avatar with the narrower
   left-hand overlay. Desktop and mobile media rules are unchanged.
   ==================================================================== */
@media (min-width: 681px) and (max-width: 1100px) {
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget {
    padding-left: clamp(120px, 13.5vw, 140px);
  }
  body:not(#layout) .pluswall-banner-avatar {
    left: 25px;
    height: clamp(82px, 9vw, 98px);
    width: clamp(82px, 9vw, 98px);
  }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 {
    font-size: clamp(23px, 2.6vw, 28px) !important;
    white-space: nowrap;
    word-break: normal;
    overflow-wrap: normal;
  }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget h1 a {
    white-space: nowrap;
    word-break: normal;
    overflow-wrap: normal;
  }
  body:not(#layout) .pluswall-cover-banner #Header1 .header-widget p {
    font-size: 12px !important;
  }
}


/* =====================================================================
   PLUSWALL 4.23 — Native Blogger threaded comments
   Only CSS is changed. Blogger owns the comment HTML, auth and controls.
   ================================================================ */
#comments .comment-thread ol,
#comments .comment-thread ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
#comments .comment-thread li {
  list-style: none;
}
#comments .comment-thread .comment {
  position: relative;
  margin: 0;
  padding: 0 0 24px;
  min-height: 36px;
}
#comments .comment .avatar-image-container {
  position: absolute;
  inset: 0 auto auto 0;
  width: 36px;
  height: 36px;
  overflow: hidden;
  border-radius: 50%;
}
#comments .comment .avatar-image-container img,
#comments .comment .avatar-image-container .avatar-icon {
  display: block;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}
#comments .comment .comment-block {
  margin: 0 0 0 48px;
  padding: 0;
  min-width: 0;
}
#comments .comment .comment-header {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 2px 10px;
  min-height: 23px;
  line-height: 1.45;
}
#comments .comment .comment-header .user,
#comments .comment .comment-header .user a,
#comments .comment .comment-header .user a:visited {
  color: #202124;
  font-style: normal;
  font-weight: 700;
  text-decoration: none;
}
#comments .comment .comment-header .datetime,
#comments .comment .comment-header .datetime a,
#comments .comment .comment-header .datetime a:visited {
  color: #777;
  font-size: 13px;
  font-style: normal;
  font-weight: 400;
  text-decoration: none;
  margin: 0;
}
#comments .comment .comment-content,
#comments .comment .comment-body {
  margin: 7px 0 0;
  line-height: 1.55;
  overflow-wrap: break-word;
}
#comments .comment .comment-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  margin: 9px 0 0;
  padding: 0;
  font-size: 13px;
  line-height: 1.5;
}
#comments .comment .comment-actions a {
  color: #777;
  text-decoration: none;
  font-weight: 500;
}
#comments .comment .comment-actions a:hover {
  color: #3367d6;
  text-decoration: underline;
}
/* Preserve Blogger-generated actions, including admin Delete.
   Do not filter links by class: Blogger's threaded comment JS can change
   class names between widget versions. Permissions remain Blogger-owned. */
/* Blogger emits a redundant "Replies" count and a trailing thread Reply. */
#comments .comment-thread .thread-count,
#comments .comment .continue {
  display: none;
}
/* Keep actual nested replies and their inline reply forms visible. */
#comments .comment .comment-replies,
#comments .comment .comment-replybox-single {
  margin: 12px 0 0 48px;
  padding: 0;
}
#comments .comment-replies .comment-replies {
  margin-left: 36px;
}
/* The older unthreaded comment form uses the same avatar/header rhythm. */
#comments #comments-block .comment {
  list-style: none;
  position: relative;
  margin: 0 0 22px;
  padding: 0;
}
#comments #comments-block .comment-block {
  margin-left: 48px;
}
#comments #comments-block .comment-author {
  font-weight: 700;
  color: #202124;
}
#comments #comments-block .comment-author a {
  color: #202124;
}
#comments #comments-block .comment-footer,
#comments #comments-block .comment-footer a {
  color: #777;
  font-size: 13px;
}
@media (max-width: 680px) {
  #comments .comment .comment-header {
    gap: 2px 8px;
  }
  #comments .comment .comment-header .datetime,
  #comments .comment .comment-header .datetime a {
    font-size: 12px;
  }
  #comments .comment .comment-replies,
  #comments .comment .comment-replybox-single {
    margin-left: 26px;
  }
  #comments .comment-replies .comment-replies {
    margin-left: 20px;
  }
}


/* PlusWall 1.0 — Blogger Link List navigation gadget */
.pluswall-collection-list > #pluswall_navigation,
.pluswall-collection-list > #pluswall_navigation > #LinkList1 {
  align-items: center;
  display: flex;
  flex: 0 0 auto;
  gap: 29px;
  margin: 0;
  min-height: 42px;
  padding: 0;
}
.pluswall-collection-list > #pluswall_navigation > #LinkList1 .pluswall-collection-link {
  flex: 0 0 auto;
}
.pluswall-banner-actions a[hidden] { display: none !important; }

/* PlusWall 1.0.3: native Blog Search gadget in the top bar. */
.pluswall-site-header-content #search_top {
  align-items:center; display:flex; flex:0 1 426px;
  margin-left:auto; max-width:426px; min-width:0; width:44vw;
}
.pluswall-site-header-content #BlogSearch1 { min-width:0; width:100%; }
.pluswall-site-header-content #BlogSearch1 .pluswall-search-form {
  margin-left:0; max-width:none; width:100%;
}
@media (max-width:680px) {
  .pluswall-site-header-content #search_top {
    flex:1 1 auto; margin-left:0; max-width:none; width:auto;
  }
}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .centered-bottom {
  position: relative;
}
body#layout .section.featured-post,
body#layout .section.main,
body#layout .section.vertical-ad-container {
  float: left;
  width: 55%;
}
body#layout .sidebar-container {
  display: inline-block;
  width: 39%;
}
body#layout .centered-bottom:after {
  clear: both;
  content: "";
  display: table;
}
body#layout .hamburger-menu,
body#layout .search {
  display: none;
}

body.script:
//
(function () {
  'use strict';

  // Home stays automatic; everything else comes from the Link List gadget.
  function setActiveCollectionLink() {
    var currentPath = window.location.pathname.replace(/\/+$/, '') || '/';
    Array.prototype.forEach.call(
      document.querySelectorAll('.pluswall-collection-link'),
      function (link) {
        var linkUrl = new URL(link.href, window.location.href);
        var linkPath = linkUrl.pathname.replace(/\/+$/, '') || '/';
        var active = linkUrl.origin === window.location.origin &&
          linkPath === currentPath &&
          (linkPath !== '/' || !window.location.search);
        link.classList.toggle('pluswall-current-collection', active);
      }
    );
  }

  function fillMissingOwnerAvatars() {
    var bannerImage = document.querySelector('.pluswall-banner-avatar-image[src]');
    var about = document.querySelector('.pluswall-about-link[href]');
    if (!bannerImage || !about) { return; }
    Array.prototype.forEach.call(document.querySelectorAll('.pluswall-post-card'), function (card) {
      if (card.querySelector('.pluswall-post-header .pluswall-author-image')) { return; }
      var author = card.querySelector('.pluswall-post-header .pluswall-author-name[href]');
      var placeholder = card.querySelector('.pluswall-post-header .pluswall-author-image-fallback');
      if (!author || !placeholder) { return; }
      var ownerId = (about.href.match(/\/profile\/(\d+)/) || [])[1];
      var authorId = (author.href.match(/\/profile\/(\d+)/) || [])[1];
      if (!ownerId || !authorId || ownerId !== authorId) { return; }
      var replacement = document.createElement('img');
      replacement.className = 'pluswall-author-image';
      replacement.alt = author.textContent.trim() + ' profile photo';
      replacement.src = bannerImage.src;
      placeholder.replaceWith(replacement);
    });
  }

  // Blogger sometimes supplies an Older Posts link even on the last label
  // page. Check the actual destination instead of guessing from card count:
  // Blogger's auto-pagination can produce short pages with more to come.
  function verifyCategoryOlderPosts() {
    if (!document.body.classList.contains('label-view')) {
      return;
    }
    var olderLink = document.querySelector('.blog-pager-older-link');
    if (!olderLink) {
      return;
    }
    var target = new URL(olderLink.href, window.location.href);
    if (target.origin !== window.location.origin) {
      return;
    }
    fetch(target.href, { credentials: 'same-origin' })
      .then(function (response) {
        if (!response.ok) { throw new Error('Older posts check failed'); }
        return response.text();
      })
      .then(function (html) {
        var nextPage = new DOMParser().parseFromString(html, 'text/html');
        var existingPostIds = {};
        Array.prototype.forEach.call(document.querySelectorAll('.pluswall-post-card[id]'), function (card) {
          existingPostIds[card.id] = true;
        });
        var nextCards = nextPage.querySelectorAll('.pluswall-post-card[id]');
        var hasNewPost = Array.prototype.some.call(nextCards, function (card) {
          return !existingPostIds[card.id];
        });
        if (!hasNewPost) {
          olderLink.style.display = 'none';
        }
      })
      .catch(function () { /* Do not suppress navigation on errors. */ });
  }

  function determineColumnCount(feedWidth) {
    if (feedWidth < 520) {
      return 1;
    }
    if (feedWidth < 900) {
      return 2;
    }
    return 3;
  }

  function initializeFeed() {
  setActiveCollectionLink();
  fillMissingOwnerAvatars();
  verifyCategoryOlderPosts();

  var postFeedElement = document.querySelector('.feed-view #page_body .blog-posts');
  if (!postFeedElement) {
    return;
  }

  var postContainerElements = Array.prototype.filter.call(postFeedElement.children, function (element) {
    return element.matches('.pluswall-post-card') || Boolean(element.querySelector('.pluswall-post-card'));
  });
  if (!postContainerElements.length) {
    return;
  }

  Array.prototype.forEach.call(postContainerElements, function (postContainerElement) {
    postContainerElement.classList.add('pluswall-post-container');
  });

  var layoutUpdatePending = false;

  function updatePostLayout() {
    layoutUpdatePending = false;
    var feedWidth = postFeedElement.clientWidth;
    if (!feedWidth) {
      return;
    }

    var columnCount = determineColumnCount(feedWidth);
    var columnGap = 14;
    var columnWidth = (feedWidth - columnGap * (columnCount - 1)) / columnCount;
    var columnHeights = [];
    var columnIndex;

    for (columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
      columnHeights.push(0);
    }

    postFeedElement.classList.add('pluswall-layout-ready');

    Array.prototype.forEach.call(postContainerElements, function (postContainerElement) {
      postContainerElement.style.width = columnWidth + 'px';
    });

    Array.prototype.forEach.call(postContainerElements, function (postContainerElement) {
      var shortestColumnIndex = 0;
      for (columnIndex = 1; columnIndex < columnCount; columnIndex += 1) {
        if (columnHeights[columnIndex] < columnHeights[shortestColumnIndex]) {
          shortestColumnIndex = columnIndex;
        }
      }

      postContainerElement.style.left = (shortestColumnIndex * (columnWidth + columnGap)) + 'px';
      postContainerElement.style.top = columnHeights[shortestColumnIndex] + 'px';
      columnHeights[shortestColumnIndex] += postContainerElement.offsetHeight + columnGap;
    });

    postFeedElement.style.height = (Math.max.apply(null, columnHeights) - columnGap) + 'px';
  }

  function requestPostLayoutUpdate() {
    if (layoutUpdatePending) {
      return;
    }
    layoutUpdatePending = true;
    window.requestAnimationFrame(updatePostLayout);
  }

  function updatePostDisplay() {
    requestPostLayoutUpdate();
  }

  window.addEventListener('load', updatePostDisplay);
  window.addEventListener('resize', requestPostLayoutUpdate);

  Array.prototype.forEach.call(postContainerElements, function (postContainerElement) {
    var mediaElements = postContainerElement.querySelectorAll('img, iframe, video');
    Array.prototype.forEach.call(mediaElements, function (mediaElement) {
      mediaElement.addEventListener('load', updatePostDisplay);
      mediaElement.addEventListener('loadedmetadata', updatePostDisplay);
    });
  });

  if (window.ResizeObserver) {
    var postResizeObserver = new ResizeObserver(updatePostDisplay);
    Array.prototype.forEach.call(postContainerElements, function (postContainerElement) {
      postResizeObserver.observe(postContainerElement);
    });
  }

  updatePostDisplay();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initializeFeed);
  } else {
    initializeFeed();
  }
}());
//
